import java.io.*;import java.nio.file.*;import java.util.zip.*;import java.security.*;import com.android.tools.smali.dexlib2.dexbacked.*;import com.android.tools.smali.dexlib2.iface.ClassDef;import com.android.tools.smali.baksmali.Adaptors.ClassDefinition;import com.android.tools.smali.baksmali.BaksmaliOptions;import com.android.tools.smali.baksmali.formatter.BaksmaliWriter;
/** Verify every other class's decoded source byte-identical to the pinned original partition. */
public class VerifyOptinPartition { public static void main(String[] a)throws Exception {byte[] b;try(ZipFile z=new ZipFile(a[0])){try(var in=z.getInputStream(z.getEntry(a[1]))){b=in.readNBytes(16*1024*1024);}}String sha=java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));if(!sha.equals(a[2]))throw new IllegalStateException("DEX identity");DexBackedDexFile d=new DexBackedDexFile(b,0);if(d.hiddenApiRestrictionsOffset!=0)throw new IllegalStateException("HiddenAPI app DEX unexpected");int unchanged=0,changed=0;for(int i=0;i<d.classCount;i++){ClassDef c=new DexBackedClassDef(d,d.classStartOffset+i*32,0);String n=c.getType().substring(1,c.getType().length()-1)+".smali";Path p=Path.of(a[3]).resolve(n);if(c.getType().equals(a[4])){changed++;continue;}var options=new BaksmaliOptions();options.localsDirective=true;options.sequentialLabels=true;options.debugInfo=true;var w=new StringWriter();new ClassDefinition(options,c).writeTo(new BaksmaliWriter(w));if(!java.util.Arrays.equals(w.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),Files.readAllBytes(p)))throw new IllegalStateException("Other class changed: "+n);unchanged++;}long count;try(var s=Files.walk(Path.of(a[3]))){count=s.filter(p->p.toString().endsWith(".smali")).count();}if(count!=d.classCount||changed!=1)throw new IllegalStateException("Class set changed");System.out.println("verifiedClasses="+d.classCount+" unchanged="+unchanged+" changed="+changed+" donorSHA="+sha);}}
